from flask import Flask, jsonify, request

app = Flask(__name__)

# Sample data for Quark's favorite sauces
sauces_data = [
    {"id": "qs1", "name": "Quantum Ketchup", "flavour": "Sweet and Atomic", "pairing": "Fries and existential crises"},
    {"id": "qs2", "name": "Graviton Gravy", "flavour": "Rich and Dense", "pairing": "Roast universe and dark matter"},
    {"id": "qs3", "name": "Spicy Gluon Glaze", "flavour": "Fiery and Bonding", "pairing": "Chicken wings and particle accelerators"},
    {"id": "qs4", "name": "Lepton Lemon Aioli", "flavour": "Light and Zesty", "pairing": "Fish and quantum entanglement"},
    {"id": "qs5", "name": "Boson Béarnaise", "flavour": "Elegant and Fundamental", "pairing": "Steak and Higgs field research"}
]

@app.route('/api/v1/quark/sauces', methods=['GET'])
def get_all_sauces():
    """
    Returns a list of all Quark's favorite sauces.
    """
    return jsonify(sauces_data)

@app.route('/api/v1/quark/sauces/<string:sauce_id>', methods=['GET'])
def get_sauce_by_id(sauce_id):
    """
    Returns a single sauce by its ID.
    """
    sauce = next((s for s in sauces_data if s["id"] == sauce_id), None)
    if sauce:
        return jsonify(sauce)
    return jsonify({"error": "Sauce not found"}), 404

@app.route('/api/v1/quark/sauces', methods=['POST'])
def add_new_sauce():
    """
    Adds a new sauce to the list. (For demonstration purposes)
    """
    new_sauce = request.json
    if not new_sauce or not all(k in new_sauce for k in ("id", "name", "flavour", "pairing")):
        return jsonify({"error": "Invalid sauce data"}), 400

    # Check for duplicate ID (simple check)
    if any(s["id"] == new_sauce["id"] for s in sauces_data):
        return jsonify({"error": "Sauce with this ID already exists"}), 409

    sauces_data.append(new_sauce)
    return jsonify(new_sauce), 201

# Run the Flask app
if __name__ == '__main__':
    # You can change the port if 5001 is already in use
    app.run(debug=True, host='0.0.0.0', port=5001)

